G.filterAutomationList=function(){const q=String(document.getElementById('autoSearch')?.value||'').toLowerCase(),status=document.getElementById('autoStatusFilter')?.value||'',trigger=document.getElementById('autoTriggerFilter')?.value||'',items=this._automation.items.filter(item=>(!q||`${item.name} ${item.description||''}`.toLowerCase().includes(q))&&(!status||item.status===status)&&(!trigger||item.trigger_type===trigger)),node=document.getElementById('automationList');if(!node)return;if(!items.length){node.innerHTML='<div class="auto-empty">No server automations match this view.<br><button onclick="G.openAutomationBuilder()">Create an automation</button></div>';return}node.innerHTML=items.map(item=>`<article class="auto-card" data-auto-id="${this.esc(item.id)}"><div class="auto-card-head"><div><strong>${this.esc(item.name)}</strong><p>${this.esc(item.description||'No description')}</p><small>${this.esc(item.trigger_type)} · next ${this.esc(item.next_run_at||'not scheduled')} · last ${this.esc(item.last_result||'never')}</small></div><span class="auto-badge ${this.esc(item.status)}">${this.esc(item.status)}</span></div><div class="auto-actions"><button onclick="G.editAutomation('${this.esc(item.id)}')">Edit</button><button onclick="G.runServerAutomation('${this.esc(item.id)}',false)">Run now</button><button onclick="G.runServerAutomation('${this.esc(item.id)}',true)">Dry run</button><button onclick="G.viewAutomationRuns('${this.esc(item.id)}')">Runs</button><button onclick="G.duplicateServerAutomation('${this.esc(item.id)}')">Duplicate</button>${item.status==='active'?`<button onclick="G.setServerAutomationStatus('${this.esc(item.id)}','pause')">Pause</button>`:`<button onclick="G.setServerAutomationStatus('${this.esc(item.id)}','enable')">Enable</button>`}<button onclick="G.confirmAutomationAction('Archive ${this.esc(item.name)}?',()=>G.setServerAutomationStatus('${this.esc(item.id)}','archive'))">Archive</button></div></article>`).join('')};
