G._blankAutomation=function(prefill={}){const ctx=this._automationContext();return{workspace_id:ctx.workspaceId,workbook_id:ctx.workbookId,name:prefill.name||'',description:prefill.description||'',status:'paused',trigger_type:prefill.trigger_type||'manual',trigger_config:prefill.trigger_config||{minute:0,hour:9,weekday:0,month_day:1,missing_day:'last_day',interval_hours:1,ignore_self_generated:true,maximum_depth:5},timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',conditions:{operator:'AND',conditions:[],groups:[]},actions:prefill.actions||[{position:0,action_type:'create_notification',name:'Notify',config:{user_ids:ctx.actorId?[ctx.actorId]:[],roles:[],title:'Automation completed',body:'The automation completed successfully.',severity:'info'},continue_on_error:false,enabled:true}],retry_policy:{max_attempts:3,initial_delay_seconds:30,multiplier:2,maximum_delay_seconds:3600,jitter_percent:20,retryable_error_codes:[]},timeout_seconds:300,max_consecutive_failures:5,dry_run_default:false,...prefill}};
